(function(root){
 'use strict';
 const F=root.Football||(typeof require==='function'?require('./engine.js'):null);
 // Original fifth-tier fiction; no fines, injuries or match bonuses are simulated here.
 const arcs=[
 {key:'shared-pitch',round:3,relation:'coach',title:'훈련장 절반의 주인',scene:'5부의 훈련장은 지역 어린이 팀과 나눠 쓴다. 한 선수가 아이들의 공을 돌려주며 웃자 다른 선수가 쏘아붙인다. “우리가 여기서 놀러 온 줄 알아?”',question:'코치가 두 선수를 떼어 놓는다. 지금 무슨 말을 할까요?',options:['각자 무엇에 화가 났는지 따로 듣는다','동료에게 화풀이하는 말부터 멈추게 한다','공간을 나눠 쓸 훈련 순서를 함께 정한다'],replies:['“웃었다고 진지하지 않은 건 아니에요.” 다른 선수는 한동안 대답하지 않는다.','“말은 심했어요. 그래도 이런 준비로 올라갈 수 있나요?” 사과와 불만이 함께 남는다.','“순서는 정할 수 있죠. 그런데 우리가 왜 여기까지 왔는지도 얘기하고 싶어요.”'],followQuestion:'코치가 묻는다. “같이 훈련하기 전에 어떻게 마무리할까요?”',followOptions:['두 사람 모두 말할 자리를 마련하자','오늘은 거리를 두고 다시 이야기하자'],finalReplies:['둘은 마주 앉지만 악수하지 않는다. 코치는 먼저 끼어들지 않고 기다린다.','각자 조끼를 챙겨 나간다. 내일도 같은 훈련장을 써야 한다는 사실은 남는다.'],echo:['따로 들어 줬던 이야기를 상대에게도 할지 망설인다.','말을 멈추게 한 일을 존중하지만 불만까지 사라진 것은 아니다.','정한 훈련 순서와 별개로 서로의 태도에 대한 오해가 남아 있다.'],later:'지역 팀이 훈련을 마치고 인사한다. 두 선수는 공을 모으다가 같은 공 앞에서 멈춘다.',last:'훈련장 문을 잠그는 코치가 그날의 다툼을 다시 꺼낸다.'},
 {key:'bus-clock',round:9,relation:'captain',title:'출발 시각을 넘긴 버스',scene:'낡은 원정 버스 앞에서 선수가 늦게 합류한다. 기다리던 동료가 가방을 밀어 놓는다. “네 사정 때문에 모두 기다려야 해?” 늦은 선수는 집에서 급한 연락을 받았다고 말한다.',question:'주장이 양쪽 이야기를 전한다. 무엇부터 확인할까요?',options:['개인 사정은 따로 듣고 기다린 동료도 만난다','사정과 별개로 연락 없이 늦은 일을 짚는다','늦을 때 누구에게 알릴지 함께 정한다'],replies:['“모두 앞에서 집안 얘기까지 하고 싶지는 않았어요.” 기다린 선수도 설명을 원한다.','“늦은 건 잘못했어요. 그렇지만 가방까지 밀칠 일인가요?” 다른 쪽의 잘못도 남는다.','“연락할 사람은 정하죠. 기다린 사람이 무시당했다고 느낀 것도 알아주세요.”'],followQuestion:'공개 사과를 요구하는 동료에게 어떻게 답할까요?',followOptions:['늦은 일은 사과하되 개인 사정은 공개하지 말자','먼저 당사자끼리 이야기하고 필요한 말만 나누자'],finalReplies:['사과는 짧게 끝난다. 버스에 올랐지만 두 사람은 다른 줄에 앉는다.','주장은 두 사람에게 자리를 내준다. 설명을 강요하지 않겠다는 말부터 전한다.'],echo:['개인 사정을 따로 들은 것은 고맙지만 기다린 사람의 마음도 남아 있다.','시간을 지키라는 지적은 받아들였지만 공개적으로 몰린 기분은 남아 있다.','연락 순서는 기억하고 있지만 서로의 태도까지 정리된 것은 아니다.'],later:'다음 원정을 준비하며 주장이 버스 좌석을 살핀다. 그날 두 사람이 했던 말이 아직 마음에 걸린다.',last:'주장이 원정 준비를 마치고 감독 옆에 앉는다. 시간표보다 먼저 사람 이야기를 꺼낸다.'},
 {key:'badge-weight',round:16,relation:'fans',title:'문장보다 무거운 이름',scene:'팬 대표가 훈련장 앞에서 선수를 붙잡는다. “토투넘 유니폼을 입고 여기 있는 게 부끄럽지도 않나요?” 선수는 “우리가 일부러 내려왔습니까?”라고 되묻는다. 주변이 조용해진다.',question:'팬 대표가 면담을 청한다. 첫마디를 어떻게 할까요?',options:['팬의 상실감과 선수의 상처를 모두 듣는다','유니폼을 향한 기대와 개인을 향한 비난을 구분한다','이번 주 함께 지킬 작은 기준부터 정한다'],replies:['“그 시절을 잃은 게 분해서요.” 선수에게 상처가 됐다는 말에는 시선을 내린다.','“비난하려던 건 아니었어요.” 잠시 뒤 “그래도 말이 심했습니다”라고 덧붙인다.','“우리가 원하는 건 호화로운 시설이 아니에요. 경기 뒤 눈을 피하지 않는 팀이죠.”'],followQuestion:'선수와 팬이 다시 만날 때 무엇을 부탁할까요?',followOptions:['서로의 말을 끊지 않고 듣자','불편한 질문에도 답할 범위를 솔직히 설명하자'],finalReplies:['만남을 약속하지만 화해를 발표하지는 않는다. 서로 들을 준비부터 해야 한다.','팬 대표는 “질문도 사람을 다치게 할 수 있겠네요”라며 목도리를 챙긴다.'],echo:['잃어버린 시절의 이야기를 들어 준 것을 기억한다.','비난의 선을 분명히 했던 말을 기억한다.','작은 기준부터 정하자는 답을 기억한다.'],later:'팬 대표가 다시 구장 문을 두드린다. 지난번 언쟁이 다른 팬들에게도 화제가 됐다고 말한다.',last:'빈 관중석에서 팬 대표가 목도리를 접는다. 다시 만난 선수의 표정보다 자신의 말을 먼저 돌아본다.'}
 ];
 function events(s,year){
  const league=year===s.year?s.league:s.history?.find(h=>h.year===year);if(league?.rules!=='five-tier'||league.division!==5)return [];
  const records=s.clubStory?.records||[],games=(year===s.year?s.statistics?.records:s.statistics?.archive?.find(a=>a.year===year)?.records)||[],complete=games.filter(r=>r.competition==='league'&&r.statisticsOriginMinute===0&&!r.unassignedGoals).sort((a,b)=>a.round-b.round),list=arcs.map(a=>({...a}));
  // The first two complete league records permanently identify the two participants.
  if(complete.length>=2){const totals=new Map();for(const g of complete.slice(0,2))for(const p of g.players){if(!F.identityProfile(p.identity))continue;totals.set(p.identity,(totals.get(p.identity)||0)+p.minutes);}const ranked=[...totals].sort((a,b)=>a[1]-b[1]||a[0].localeCompare(b[0]));let pair;
   for(const low of ranked){const high=[...ranked].reverse().find(p=>p[1]>low[1]&&F.identityProfile(p[0]).pos===F.identityProfile(low[0]).pos);if(high){pair=[low,high];break;}}
   if(pair){const [[actor,minutes],[other,otherMinutes]]=pair,A=F.identityProfile(actor).name,B=F.identityProfile(other).name;
    list.push({key:'bench-friction',round:complete[1].round,relation:'captain',actor,participants:[actor,other],title:'같은 자리, 다른 출전 시간',scene:'첫 두 확정 리그 경기: '+A+' '+minutes+'분, '+B+' '+otherMinutes+'분. 조끼를 정리하던 '+A+'의 목소리가 높아진다. “내가 여기서 뭘 더 해야 하죠?” '+B+'도 돌아선다. “내가 네 자리를 빼앗았다는 거야?”',question:'두 선수가 감독의 답을 기다립니다.',options:['서로를 탓하기 전에 각자 느낀 점을 듣는다','선발 결정의 책임은 감독에게 있다고 말한다','출전 기록과 다음 선택 기준을 함께 설명한다'],replies:[A+': “동료가 싫은 게 아니에요. 잊힌 것 같아서요.” '+B+': “나도 매번 자리를 지켜야 한다는 부담이 있어.”',B+': “감독님 결정인 건 알아요.” '+A+': “그럼 제게도 직접 이유를 말해 주세요.”',A+': “분 단위 기록은 알아요. 그다음 무엇을 준비해야 하는지 듣고 싶어요.” '+B+'도 고개를 든다.'],followQuestion:'다음 선발을 보장하지 않고 무엇을 약속할까요?',followOptions:['두 경기 뒤 출전 기록을 함께 다시 보자','출전 보장 없이 선택 이유를 다시 설명하자'],finalReplies:['둘은 훈련장으로 돌아간다. 선발은 그대로다. 다음 두 리그 경기의 실제 출전 기록을 본 뒤 다시 만나기로 한다.','출전 약속은 하지 않았다. 두 사람은 납득하지 못한 부분을 다음에 다시 말하기로 한다.'],echo:['서로의 답답함을 먼저 들었던 말','감독이 선발 결정의 책임을 지겠다는 말','출전 기록과 준비 기준을 설명하겠다는 말'],later:'두 선수가 지난 면담 뒤 확정된 리그 출전 기록을 펼친다.',last:'같은 포지션의 두 선수가 다시 감독실 문 앞에 선다. 경쟁은 끝나지 않았지만 지난 대화를 없던 일로 하지는 않는다.'});}
  }
  const out=[];
  for(const arc of list){const id=year+':'+arc.key,first=records.find(r=>r.event===id&&r.step===0),done=records.find(r=>r.event===id&&r.step===1),base={...arc,conflict:true,speaker:{captain:'선수단 갈등',coach:'수석 코치',fans:'팬 대표'}[arc.relation]};
   const present=!arc.participants||year!==s.year||arc.participants.every(identity=>Object.values(s.squad).some(p=>p.identity===identity));
   if(!present&&!first)continue;out.push(base);if(!first||!done||done.atRound+2>46)continue;
   const approach=['listen','bold','practical'].indexOf(first.choice),round=done.atRound+2,key=arc.key+'-meeting';let evidence='',playedMinutes=null;
   if(arc.participants){const after=complete.filter(g=>g.round>done.atRound&&g.round<=round);if(after.length<2)continue;playedMinutes=after.reduce((sum,g)=>sum+(g.players.find(p=>p.identity===first.actor)?.minutes||0),0);evidence=arc.participants.map(identity=>F.identityProfile(identity).name+' '+after.reduce((sum,g)=>sum+(g.players.find(p=>p.identity===identity)?.minutes||0),0)+'분').join(' · ')+'. ';}
   if(!present&&!records.some(r=>r.event===year+':'+key))continue;
   const meeting={...base,key,round,actor:first.actor,title:'다시 마주 앉은 날 · '+arc.title,scene:evidence+arc.later+' '+arc.echo[approach]+' “'+arc.followOptions[done.choice==='commit'?0:1]+'”라는 답도 기억한다.',question:playedMinutes===0?'면담 뒤 두 리그 경기에서도 제 출전은 0분이에요. 다음에는 무엇을 준비해야 하죠?':playedMinutes>0?'면담 뒤 '+playedMinutes+'분을 뛰었습니다. 그래도 경쟁하는 동료와는 어떻게 지내야 할까요?':approach===1?'그날의 기준은 알겠어요. 그래도 서운한 마음까지 잘못인가요?':'한 번 이야기했다고 편해지지는 않네요. 다음에는 어떻게 할까요?',options:['남아 있는 서운함도 말할 수 있게 하자','동료를 공격하는 행동에는 같은 기준을 지키자','아직 합의하지 못한 한 가지부터 정리하자'],replies:['“이제 괜찮다고 답해야 할 줄 알았어요.” 잠시 침묵한 뒤 이야기가 이어진다.','“선을 지키겠습니다. 대신 불만을 말하는 것까지 막지는 말아 주세요.”','“전부 풀렸다고 하지 않을게요. 오늘 정할 수 있는 것부터 말하죠.”'],followQuestion:'면담을 끝내기 전에 어떤 말을 남길까요?',followOptions:['해결되지 않은 부분도 다음에 다시 듣겠다','누구 편인지보다 같은 기준을 설명하겠다'],finalReplies:['갈등이 끝났다는 발표 대신 다시 대화할 자리가 남았다.','기준은 공유했지만 모든 감정이 같아지지는 않았다. 그 차이도 기록에 남긴다.']};out.push(meeting);
   const next=records.find(r=>r.event===year+':'+key&&r.step===0),end=records.find(r=>r.event===year+':'+key&&r.step===1);if(!next||!end||end.atRound+2>46)continue;
   out.push({...base,key:arc.key+'-aftermath',round:end.atRound+2,actor:first.actor,title:'남은 말 · '+arc.title,scene:arc.last+' '+(next.choice==='listen'?'서운함도 말해도 된다던 답이 대화의 시작이 된다.':next.choice==='bold'?'서로를 공격하지 말자던 기준을 다시 확인한다.':'합의하지 못한 한 가지부터 정리하자던 답을 꺼낸다.'),question:end.choice==='commit'?'다시 말해도 된다고 하셨죠. 아직 어려운 부분이 있어요.':'같은 기준을 설명하겠다고 하셨죠. 제 입장에서도 이해하고 싶어요.',options:['갈등이 남았다고 대화를 실패로 보지는 말자','동료를 존중하면서 경쟁하는 기준을 지키자','다음 준비에서 서로에게 필요한 것을 하나씩 말하자'],replies:['“억지로 화해한 척하지 않아도 되는군요.” 대답이 처음보다 천천히 나온다.','“친해지는 것과 존중하는 것은 다르겠죠. 그 선은 지키겠습니다.”','“제가 먼저 필요한 걸 말할게요. 상대의 답도 듣겠습니다.”'],followQuestion:'이 일을 어떤 기억으로 남길까요?',followOptions:['말하기 어려운 일도 꺼낼 수 있었던 시작','계속 지켜야 할 기준을 함께 정한 날'],finalReplies:['완벽한 화해는 아니다. 그래도 다음에 문제가 생겼을 때 찾아갈 문은 알고 있다.','갈등을 지워 버리지는 않았다. 서로 다른 마음으로도 같은 팀에서 준비하는 법을 배워 간다.']});
  }
  return out;
 }
 const api={events};root.StoryConflicts=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
